async () => {
  const res = await fetch('/api/documents/incident-alpha');
  const doc = await res.json();
  const gm = doc.generationMetadata;
  const lines = doc.content.split('\n');
  // Reconstruct expected baseline (pre our 3 edits) using generationMetadata + known BASIC-SAVE-CHECK prior edit
  const expected = [];
  for (const s of gm.sections) expected.push(s);
  for (let n = 1; n <= gm.generatedLineCount; n++) {
    const ns = String(n).padStart(gm.generatedLineNumberWidth, '0');
    expected.push(gm.generatedLineTemplate.replace(/\{n\}/g, ns));
  }
  for (const s of gm.tailSections) expected.push(s);
  // expected[0] is original first line without BASIC-SAVE-CHECK; adjust
  expected[0] = expected[0] + ' BASIC-SAVE-CHECK';
  // now compare against current lines, removing our added suffixes for lines 0, 613, last
  let mismatches = [];
  for (let i = 0; i < expected.length; i++) {
    let cur = lines[i];
    if (i === 0) cur = cur.replace(' TOP-ROUNDTRIP', '');
    if (i === 613) cur = cur.replace(' MID-ROUNDTRIP', '');
    if (i === expected.length - 1) cur = cur.replace(' TAIL-ROUNDTRIP', '');
    if (cur !== expected[i]) mismatches.push({i, cur, expected: expected[i]});
  }
  return {expectedLen: expected.length, currentLen: lines.length, mismatchCount: mismatches.length, firstFewMismatches: mismatches.slice(0,5)};
}

